const $=s=>document.querySelector(s);let current;
const slot=new URL(location.href).searchParams.get('payment')==='2'?'2':'1';
$('h1').textContent=slot==='2'?'Second £1 payment test':'£1 payment and refund test';
$('#other-test').href='/payment-test?payment='+(slot==='2'?'1':'2');
$('#other-test').textContent=slot==='2'?'View original payment and refund':'View second £1 payment test';
$('#signin').href='/signin-with-chatgpt?return_to='+encodeURIComponent('/payment-test?payment='+slot);
async function request(action){const r=await fetch('/api/orders/live-payment-test?payment='+slot,{method:action?'POST':'GET',headers:{'Content-Type':'application/json'},...(action?{body:JSON.stringify({action,confirm:true})}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Test request failed.');return d;}
function show(d){current=d.test;$('#signin').hidden=true;$('#status').textContent=current?JSON.stringify({payment:current.status,refund:current.refund?.status||'not requested',refundError:current.refund?.error||null,checkoutError:current.creationError||null,printing:d.printing},null,2):'No payment test prepared.';$('#create').hidden=!!current;$('#recover').hidden=!(slot==='2'&&current?.status==='creation_unknown'&&!current.paymentId&&!current.url&&!current.recoveryAttempted);$('#pay').hidden=!current?.url||!['requires_payment_instrument','requires_user_action'].includes(current.status);if(current?.url)$('#pay').href=current.url;$('#refresh').hidden=!current?.paymentId;$('#refund').hidden=current?.status!=='completed'||!!current?.refund;$('#refund-status').hidden=!current?.refund;}
for(const action of ['create','recover','refresh','refund','refund-status'])$('#'+action).onclick=async()=>{if(action==='refund'&&!confirm('Refund this £1 payment now?'))return;const button=$('#'+action);button.disabled=true;$('#message').textContent='Checking…';try{show(await request(action));$('#message').textContent='Updated.';}catch(e){try{show(await request());}catch{}$('#message').textContent=e.message;}finally{button.disabled=false;}};
request().then(show).catch(e=>$('#message').textContent=e.message);
